$env=GreenPortalDatabase::env(); $pdo=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');
$user=(int)($_SESSION['usuario']['codusuario']??0); if(empty($_SESSION['migracao_menu_csrf'])) $_SESSION['migracao_menu_csrf']=bin2hex(random_bytes(32)); $csrf=(string)$_SESSION['migracao_menu_csrf'];
$msg='';$err='';
try { if($_SERVER['REQUEST_METHOD']==='POST'){ if(!hash_equals($csrf,(string)($_POST['csrf']??''))) throw new RuntimeException(adm_t('Token de seguranca invalido.'));
  AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menu_nao_mapeado_associar',[(int)$_POST['codregistro'],trim((string)$_POST['banco_destino']),((int)($_POST['codmenu_destino']??0)), $user, strtoupper(trim((string)$_POST['status']))]);
  $msg=adm_t('Validacao do menu registrada.');
} } catch(Throwable $e){$err=$e->getMessage();}
$destino=trim((string)($_GET['destino']??'')); $status=strtoupper(trim((string)($_GET['status']??'PENDENTE'))); $busca=trim((string)($_GET['q']??''));
$total=(int)(AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menus_nao_mapeados_count',[$destino,$status,$busca])[0]['total']??0);
$rows=AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menus_nao_mapeados_listar',[$destino,$status,$busca,500,0]);
$menus=$pdo->query("SELECT codmenu,codigo,label,modulo FROM menus WHERE ativo=1 ORDER BY COALESCE(modulo,''),label")->fetchAll(PDO::FETCH_ASSOC);
$destinos=$pdo->query("SELECT DISTINCT banco_destino FROM migracao_menus_nao_mapeados ORDER BY banco_destino")->fetchAll(PDO::FETCH_COLUMN);
